{
  $schema: "https://docs.renovatebot.com/renovate-schema.json",
  extends: ["config:recommended"],
  timezone: "Asia/Jerusalem",
  schedule: ["* 2-6 1 * *"],
  minimumReleaseAge: "7 days",
  packageRules: [
    { matchManagers: ["npm"], groupName: "npm" },
    { matchManagers: ["github-actions"], groupName: "github actions" },
    { matchManagers: ["dockerfile"], groupName: "base images" },
    { matchUpdateTypes: ["major"], groupName: null },
  ],
}

// the branch list after this change:
// renovate/actions-setup-node-7.x  actions/setup-node → v7.1.0 (major)
// renovate/github-actions  actions/checkout → v7.0.1 (patch)
// renovate/node-24.x  node → 24.22.0 (major)
// renovate/npm  typescript → 5.9.3 (minor)
// renovate/typescript-7.x  typescript → 7.0.2 (major)
